<?php $page_title='Sales & Invoices'; require_once __DIR__.'/../includes/header.php'; require_perm($pdo,'sales','can_view'); $msg=''; $invoice=null;
$custs=$pdo->query("SELECT * FROM customers ORDER BY name")->fetchAll(); $whs=$pdo->query("SELECT * FROM warehouses ORDER BY name")->fetchAll(); $prods=$pdo->query("SELECT * FROM products ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $cust=(int)$_POST['customer_id']; $wh=(int)$_POST['warehouse_id']; $pid=(int)$_POST['product_id']; $qty=(int)$_POST['quantity']; $date=clean($_POST['sale_date']??date('Y-m-d')); $pay=clean($_POST['payment_method']??'Cash');
 $pr=$pdo->prepare("SELECT * FROM products WHERE id=?"); $pr->execute([$pid]); $prod=$pr->fetch(); $price=(float)$prod['selling_price']; $total=$qty*$price;
 try{ $pdo->beginTransaction(); $avail=$pdo->prepare("SELECT COALESCE(quantity,0) FROM stock WHERE product_id=? AND warehouse_id=?"); $avail->execute([$pid,$wh]); if((int)$avail->fetchColumn() < $qty) throw new Exception('Insufficient stock for this sale. Available: '.$avail->fetchColumn()); $no=gen_no('INV'); $pdo->prepare("INSERT INTO sales(invoice_no,customer_id,warehouse_id,total_amount,payment_method,sale_date,created_by) VALUES(?,?,?,?,?,?,?)")->execute([$no,$cust,$wh,$total,$pay,$date,$_SESSION['user_id']]); $sid=(int)$pdo->lastInsertId(); $pdo->prepare("INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,subtotal) VALUES(?,?,?,?,?)")->execute([$sid,$pid,$qty,$price,$total]); adjust_stock($pdo,$pid,$wh,-$qty,'sale',$no,'Sale'); $pdo->commit(); $msg='Sale completed: '.$no.' - stock deducted.'; $invoice=['no'=>$no,'cust'=>$cust,'total'=>$total,'qty'=>$qty,'product'=>$prod['name'],'price'=>$price,'date'=>$date,'pay'=>$pay]; audit_log($pdo,'Create Sale','sales',"Sale $no total $total"); }catch(Exception $e){ if($pdo->inTransaction()) $pdo->rollBack(); $msg='Error: '.e($e->getMessage()); }
}
$rows=$pdo->query("SELECT s.*, c.name as cust, w.name as wname FROM sales s JOIN customers c ON c.id=s.customer_id JOIN warehouses w ON w.id=s.warehouse_id ORDER BY s.id DESC LIMIT 100")->fetchAll();
?>
<?php if($msg): ?><div class="alert alert-info"><?= e($msg) ?></div><?php endif; ?>
<?php if($invoice): ?><div class="card p-4 mb-3"><h4>🧾 Invoice <?= e($invoice['no']) ?></h4><p>Date: <?= e($invoice['date']) ?> | Payment: <?= e($invoice['pay']) ?></p><table class="table"><tr><th>Product</th><th>Qty</th><th>Price</th><th>Total</th></tr><tr><td><?= e($invoice['product']) ?></td><td><?= (int)$invoice['qty'] ?></td><td><?= money($invoice['price']) ?></td><td><?= money($invoice['total']) ?></td></tr></table><button class="btn btn-secondary" onclick="window.print()">Print Invoice</button></div><?php endif; ?>
<div class="row"><div class="col-md-4"><div class="card p-3"><h5>New Sale</h5><form method="post"><?= csrf_field() ?><label class="form-label">Customer</label><select name="customer_id" class="form-select mb-2" required><?php foreach($custs as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select><label class="form-label">Warehouse</label><select name="warehouse_id" class="form-select mb-2" required><?php foreach($whs as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">Product</label><select name="product_id" class="form-select mb-2" required><?php foreach($prods as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?> - <?= money($p['selling_price']) ?></option><?php endforeach; ?></select><label class="form-label">Quantity</label><input type="number" min="1" name="quantity" class="form-control mb-2" required><label class="form-label">Payment Method</label><select name="payment_method" class="form-select mb-2"><option>Cash</option><option>Transfer</option><option>Card</option><option>Credit</option></select><label class="form-label">Date</label><input type="date" name="sale_date" value="<?= date('Y-m-d') ?>" class="form-control mb-2"><button class="btn btn-success">Complete Sale</button></form></div></div>
<div class="col-md-8"><div class="card p-3"><h5>Sales History</h5><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Customer</th><th>Warehouse</th><th>Total</th><th>Payment</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['invoice_no']) ?></td><td><?= e($r['cust']) ?></td><td><?= e($r['wname']) ?></td><td><?= money($r['total_amount']) ?></td><td><?= e($r['payment_method']) ?></td><td><?= e($r['sale_date']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
